export interface SandboxPolicy {
  image: string;                 // pinned by digest, not by tag
  networkEgress: string[];       // host:port allowlist, ["none"] for fully offline
  readOnlyRoot: true;
  tmpfsMb: number;
  memoryMb: number;
  cpus: number;
  timeoutMs: number;
  maxStdoutBytes: number;
  dropCapabilities: string[];    // ["ALL"]
  runAsUser: number;             // non-root
  seccompProfile: "default" | "strict";
  envAllowlist: string[];        // no secrets, ever
}

export const PYTHON_SNIPPET_SANDBOX: SandboxPolicy = {
  image: "registry.internal/python@sha256:â€¦",   // pin by digest
  networkEgress: ["none"],
  readOnlyRoot: true,
  tmpfsMb: 256,
  memoryMb: 512,
  cpus: 1,
  timeoutMs: 5_000,
  maxStdoutBytes: 256 * 1024,
  dropCapabilities: ["ALL"],
  runAsUser: 65532,
  seccompProfile: "strict",
  envAllowlist: ["PATH", "PYTHONHASHSEED", "HOME"],
};

export async function runInSandbox(
  code: string, policy: SandboxPolicy, inputs: { [k: string]: unknown },
): Promise<{ stdout: string; stderr: string; exitCode: number; timedOut: boolean; truncated: boolean }> {
  const imageRef = await resolveImageByDigest(policy.image);        // never :latest
  const proc = await containerRuntime.create({
    image: imageRef,
    command: ["/usr/local/bin/python", "-I", "-S", "-c", code],
    stdin: JSON.stringify(inputs),                                  // via pipe, not a file
    mounts: [{ source: "tmpfs", target: "/tmp", sizeMb: policy.tmpfsMb, options: ["rw"] }],
    readOnlyRootFilesystem: policy.readOnlyRoot,
    memoryMb: policy.memoryMb,
    cpus: policy.cpus,
    network: policy.networkEgress.length === 1 && policy.networkEgress[0] === "none"
      ? { none: true }
      : { allowlist: policy.networkEgress, enforce: true, logDenied: true },
    user: policy.runAsUser,
    capabilities: { drop: policy.dropCapabilities },
    seccomp: policy.seccompProfile,
    env: policy.envAllowlist.map((k) => `${k}=${process.env[k] ?? ""}`),
    timeoutMs: policy.timeoutMs,
    killSignal: "SIGKILL",
  });

  const out = await proc.stdout();
  const err = await proc.stderr();
  return {
    stdout: out.bytes(0, policy.maxStdoutBytes),
    stderr: err.bytes(0, 64 * 1024),
    exitCode: await proc.exitCode(),
    timedOut: await proc.timedOut(),
    truncated: out.length > policy.maxStdoutBytes,
  };
}
