export interface AutonomyPolicy {
  toolName: string;
  level: "always_ask" | "ask_below_threshold" | "autonomous";
  threshold?: { amountCents?: number; itemCount?: number; confidence?: number };
  enabledForTenants: string[];
}

export function needsApproval(p: AutonomyPolicy, risk: RiskClassification, args: unknown, conf?: number): boolean {
  if (p.level === "always_ask") return true;
  if (p.level === "autonomous") return false;
  const t = p.threshold ?? {};
  const amount = (args as any)?.amountCents;
  const count = (args as any)?.items?.length ?? 1;
  if (t.amountCents != null && typeof amount === "number" && amount > t.amountCents) return true;
  if (t.itemCount != null && count > t.itemCount) return true;
  if (t.confidence != null && conf != null && conf < t.confidence) return true;
  return risk.level === "security";
}
