```ts
// Price table in configuration, not in code. Never hard-code a rate in logic.
export interface ModelPricing {
  modelId: string;
  inputPerMTok: number;          // USD per million tokens
  outputPerMTok: number;
  cachedInputPerMTok: number;
  cacheWritePerMTok?: number;
  batchDiscount?: number;        // fraction, e.g. 0.5
  tier?: string;                 // pricing tier / region / commitment
}

export interface CostBreakdown {
  totalCents: number;
  byComponent: Record<"input" | "output" | "cacheRead" | "cacheWrite" | "embed" | "rerank" | "judge", number>;
  inputTokens: number;
  outputTokens: number;
  cacheReadTokens: number;
}

export function costOf(usage: Usage, pricing: ModelPricing, component: CostKey = "generation"): CostBreakdown {
  const rates: Record<CostKey, [number, number, number, number]> = {
    generation: [pricing.inputPerMTok, pricing.outputPerMTok, pricing.cachedInputPerMTok, pricing.cacheWritePerMTok ?? 0],
    embed: [pricing.inputPerMTok, 0, 0, 0],
    rerank: [pricing.inputPerMTok, 0, 0, 0],
    judge: [pricing.inputPerMTok, pricing.outputPerMTok, pricing.cachedInputPerMTok, 0],
  };
  const [inRate, outRate, cacheRate, writeRate] = rates[component];
  const M = 1_000_000;
  const freshInput = Math.max(0, usage.inputTokens - usage.cachedInputTokens);

  const byComponent = {
    input: round4((freshInput / M) * inRate),
    output: round4((usage.outputTokens / M) * outRate),
    cacheRead: round4((usage.cachedInputTokens / M) * cacheRate),
    cacheWrite: 0,
    embed: 0,
    rerank: 0,
    judge: 0,
  };
  return {
    totalCents: round4(byComponent.input + byComponent.output + byComponent.cacheRead),
    byComponent,
    inputTokens: usage.inputTokens,
    outputTokens: usage.outputTokens,
    cacheReadTokens: usage.cachedInputTokens,
  };
}

// Attribute cost to the causal feature, not just to the endpoint.
export interface SpendRecord {
  requestId: string;
  tenantId: string;
  userId: string;
  feature: string;              // "support.reply", "rag.answer", "agent.run"
  model: string;
