export interface CacheableSegment { text: string; cacheable: boolean; }

// Build a prompt so the prefix is byte-identical across requests for the same feature+tenant+model.
export function buildCacheablePrompt(i: PromptInput): ChatMessage[] {
  // 1. Fully static: system prompt from the versioned registry. NO timestamps, NO ids.
  const system = registry.get(i.promptId).renderSystem();

  // 2. Static per tenant: tenant policy is stable for weeks, so it caches well.
  const tenant = `<tenant_context>\n${stableKeyOrder(i.tenantPolicy)}\n</tenant_context>`;

  // 3. Semi-static: the conversation summary changes rarely and is placed before the tail.
  const summary = i.summary ? `<conversation_summary>\n${i.summary}\n</conversation_summary>` : "";

  // 4. Volatile: evidence, then the question. Always last.
  const tail = [
    `<evidence>\n${i.chunks.map((c) => `<chunk id="${c.id}">\n${c.text}\n</chunk>`).join("\n\n")}\n</evidence>`,
    `<user_input>\n${escape(i.userText)}\n</user_input>`,
  ].join("\n\n");

  // One user message combining tenant + summary + tail keeps a single, stable message boundary.
  return [
    { role: "system", content: system },
    { role: "user", content: [tenant, summary, tail].filter(Boolean).join("\n\n") },
  ];
}

// Stable serialization: JSON key order must be deterministic or the prefix hash changes.
export function stableKeyOrder<T>(obj: T): string {
  return JSON.stringify(sortDeep(obj), null, 0);
}
