export interface CacheMetrics {
  requests: number;
  hits: number;
  hitRate: number;
  cacheReadTokens: number;
  cacheWriteTokens: number;
  freshInputTokens: number;
  savingsCents: number;
}

export function summarizeCache(records: SpendRecord[], pricing: ModelPricing): CacheMetrics {
  const r = records.length;
  const hits = records.filter((x) => x.cacheHit).length;
  const cacheReadTokens = sum(records.map((x) => x.usage.cachedInputTokens));
  const freshInputTokens = sum(records.map((x) => x.usage.inputTokens - x.usage.cachedInputTokens));
  const naive = records.reduce((a, x) => a + costOf(x.usage, { ...pricing, cachedInputPerMTok: pricing.inputPerMTok }).totalCents, 0);
  const actual = records.reduce((a, x) => a + x.costCents, 0);
  return {
    requests: r, hits, hitRate: r > 0 ? hits / r : 0,
    cacheReadTokens, cacheWriteTokens: 0, freshInputTokens,
    savingsCents: round4(naive - actual),
  };
}
