  hitCount: number;
  ttlSeconds: number;
}

export interface SemanticCacheConfig {
  similarityThreshold: number;   // tune on your data; too low = wrong answers, too high = no hits
  maxAgeSeconds: number;
  namespaceBy: ("tenant" | "promptHash" | "model")[];
}

export async function semanticCacheLookup(
  query: string, cfg: SemanticCacheConfig, ctx: { tenantId: string; promptHash: string; model: string },
): Promise<{ hit: SemanticCacheEntry; score: number } | null> {
  const [qv] = await embedder.embed([query], "query");
  const hits = await cacheIndex.search(qv, 3, {
    namespace: buildNamespace(cfg.namespaceBy, ctx),
    maxAgeSeconds: cfg.maxAgeSeconds,
  });
  const best = hits[0];
  if (!best || best.score < cfg.similarityThreshold) return null;
  // Never serve across differing prompts/models even at high similarity.
  if (best.entry.promptHash !== ctx.promptHash) return null;
  return { hit: best.entry, score: best.score };
}
