export type ModelClass = "fast" | "standard" | "deep";

export interface RoutingDecision {
  tier: ModelClass;
  reason: string;
  estimatedCostCents: number;
  fallbacks: ModelClass[];
}

export interface RoutingSignals {
  inputTokens: number;
  requiresReasoning: boolean;
  requiresCode: boolean;
  hasMultiStepTask: boolean;
  toolCount: number;
  retrievalConfidence?: number;
  tenantTier: "free" | "pro" | "enterprise";
}

export function route(signals: RoutingSignals, budgetCents: number): RoutingDecision {
  const tiers: Record<ModelClass, string> = { fast: FAST_MODEL, standard: DEFAULT_MODEL, deep: DEEP_MODEL };

  let tier: ModelClass = "fast";
  let reason = "default fast path";

  if (signals.requiresReasoning || signals.requiresCode) { tier = "deep"; reason = "reasoning or code required"; }
  else if (signals.hasMultiStepTask || signals.toolCount > 4) { tier = "standard"; reason = "multi-step task"; }
  else if (signals.inputTokens > 8_000) { tier = "standard"; reason = "large context"; }
  else if (signals.retrievalConfidence !== undefined && signals.retrievalConfidence < 0.5) {
    tier = "standard"; reason = "low retrieval confidence; synthesis needed";
  }

  if (signals.tenantTier === "free" && tier === "deep") {
    tier = "standard"; reason += "; downgraded for free tier";
  }
  const est = estimateCost(tiers[tier], signals.inputTokens);
  if (est > budgetCents) {
    return { tier: "fast", reason: reason + "; budget forced fast path", estimatedCostCents: est, fallbacks: [] };
  }
  return {
    tier, reason, estimatedCostCents: est,
    fallbacks: tier === "deep" ? ["standard", "fast"] : tier === "standard" ? ["fast"] : [],
  };
}
