```ts
export async function cascade<T>(
  input: PromptInput,
  verify: (out: T) => Promise<{ ok: boolean; confidence: number; reason: string }>,
  tiers: ModelClass[] = ["fast", "standard", "deep"],
): Promise<{ output: T; tier: ModelClass; attempts: Attempt[]; escalated: boolean }> {
  const attempts: Attempt[] = [];
  let lastOutput: T | null = null;

  for (const tier of tiers) {
    const start = Date.now();
    const res = await generate(input, MODEL_BY_TIER[tier]);
    const parsed = validate(res);                 // schema + business rules
    attempts.push({ tier, latencyMs: Date.now() - start, usage: res.usage,
      stopReason: res.stopReason, valid: parsed.ok });
    if (!parsed.ok) continue;                     // schema failure: escalate, do not repair here
    lastOutput = parsed.value as T;

    const v = await verify(lastOutput);
    if (v.ok && v.confidence >= CONFIDENCE_FLOOR) {
      return { output: lastOutput, tier, attempts, escalated: tier !== tiers[0] };
    }
    // Verification failed or confidence low: escalate.
  }
  // All tiers failed verification. Return the best attempt and flag it, or fall back deterministically.
  return { output: lastOutput as T, tier: tiers[tiers.length - 1], attempts, escalated: true };
}
