export async function selfConsistentOrEscalate<T>(input: PromptInput): Promise<{ value: T; agreed: boolean; costCents: number }> {
  const [a, b] = await Promise.all([
    generate(input, FAST_MODEL, { temperature: 0.2, seed: 1 }),
    generate(input, FAST_MODEL, { temperature: 0.8, seed: 2 }),
  ]);
  const va = validate(a), vb = validate(b);
  if (va.ok && vb.ok && stableKeyOrder(va.value) === stableKeyOrder(vb.value)) {
    return { value: va.value as T, agreed: true, costCents: costOf(a.usage).totalCents + costOf(b.usage).totalCents };
  }
  const deep = await generate(input, DEEP_MODEL);
  return { value: validate(deep).value as T, agreed: false, costCents: costOf(deep.usage).totalCents };
}
