```ts
export async function processJob(job: AiJob, worker: WorkerContext): Promise<void> {
  const deadline = Date.now() + (worker.jobTimeoutMs ?? 15 * 60_000);
  const heartbeat = setInterval(() => void touchHeartbeat(job.id), 30_000);

  try {
    const handler = HANDLERS[job.type];
    if (!handler) throw new PermanentError(`unknown job type ${job.type}`);

    const progress = await loadProgress(job.id);       // partial results from a prior attempt
    const result = await handler(job, {
      deadline,
      progress,
      signal: worker.signal,
      // Budget check before every billable operation.
      async beforeSpend(centsEstimate: number): Promise<void> {
        const fresh = await db.one(`SELECT spent_cents, budget_cents FROM ai_jobs WHERE id = $1`, [job.id]);
        if (fresh.spent_cents + centsEstimate > fresh.budget_cents) {
          throw new PermanentError("budget exceeded");
        }
      },
      async saveProgress(p: unknown): Promise<void> {
        // Persist partial progress so a retry resumes instead of restarting.
        await db.query(`UPDATE ai_jobs SET payload = payload || $2::jsonb WHERE id = $1`,
          [job.id, JSON.stringify({ progress: p })]);
      },
    });

    await db.query(
      `UPDATE ai_jobs SET status = 'succeeded', result_ref = $2, finished_at = now(), spent_cents = $3
        WHERE id = $1`, [job.id, result.ref, result.spentCents]);
    await notify(job, { status: "succeeded", ref: result.ref });
  } catch (err) {
    const retryable = classifyJobError(err) === "transient";
    const exhausted = job.attempts >= job.maxAttempts;
    const status = !retryable || exhausted ? (exhausted ? "dead" : "failed") : "queued";
    await db.query(
      `UPDATE ai_jobs SET status = $2, error_code = $3, finished_at = CASE WHEN $2 <> 'queued' THEN now() END
        WHERE id = $1`, [job.id, status, (err as Error).message.slice(0, 200)]);
    if (status !== "queued") await notify(job, { status, error: publicMessage(err) });
    if (status === "dead") await alertOncall({ jobId: job.id, error: String(err) });
  } finally {
    clearInterval(heartbeat);
  }
}
