export type QualityTier = "full" | "reduced_context" | "fast_model" | "deterministic" | "error";

export async function withLatencyBudget<T>(
  primary: () => Promise<T>,
  fallbacks: Partial<Record<Exclude<QualityTier, "full" | "error">, () => Promise<T>>>,
  budgetMs: number,
): Promise<{ value: T; tier: QualityTier; elapsedMs: number }> {
  const t0 = Date.now();
  try {
    const value = await withTimeout(primary(), budgetMs);
    return { value, tier: "full", elapsedMs: Date.now() - t0 };
  } catch (err) {
    const elapsed = Date.now() - t0;
    for (const [tier, fn] of Object.entries(fallbacks) as [QualityTier, () => Promise<T>][]) {
      if (elapsed > budgetMs) break;
      try { return { value: await withTimeout(fn(), budgetMs - elapsed), tier, elapsedMs: Date.now() - t0 }; }
      catch { /* try the next tier */ }
    }
    throw err;
  }
}
