```ts
export interface ConversationCostProjection {
  turns: number;
  naiveFullHistoryTokens: number;
  windowedTokens: number;
  summarizedTokens: number;
  naiveCostCents: number;
  windowedCostCents: number;
  summarizedCostCents: number;
  savingsRatio: number;
}

export function projectConversationCost(
  turns: number, avgTurnOutputTokens: number, avgUserTokens: number,
  pricing: ModelPricing, { windowTurns = 6, summaryTokens = 500 }: {
    windowTurns?: number; summaryTokens?: number;
  } = {},
): ConversationCostProjection {
  const perTurnNew = avgTurnOutputTokens + avgUserTokens;
  let naive = 0, windowed = 0, summarized = 0;
  for (let n = 1; n <= turns; n++) {
    naive += perTurnNew * n;                                     // full history resent
    const historyWindow = Math.min(n - 1, windowTurns);
    windowed += perTurnNew + historyWindow * perTurnNew;
    summarized += perTurnNew + Math.min(summaryTokens, n * perTurnNew * 0.2);
  }
  const c = (t: number) => round4((t / 1_000_000) * (pricing.inputPerMTok + pricing.outputPerMTok));
  return {
    turns,
    naiveFullHistoryTokens: naive,
    windowedTokens: windowed,
    summarizedTokens: summarized,
    naiveCostCents: c(naive),
    windowedCostCents: c(windowed),
    summarizedCostCents: c(summarized),
    savingsRatio: naive > 0 ? 1 - c(summarized) / c(naive) : 0,
  };
}
