export async function maybeCompact(
  store: ConversationStore, conversationId: string,
  cfg: { windowTokens: number; triggerFraction: number; keepRecentTurns: number; maxSummaryTokens: number },
): Promise<{ compacted: boolean; summaryTokens: number }> {
  const msgs = await store.history(conversationId);
  const total = msgs.reduce((n, m) => n + measure(m), 0);
  const trigger = cfg.windowTokens * cfg.triggerFraction - cfg.maxSummaryTokens;
  if (total < trigger) return { compacted: false, summaryTokens: 0 };

  const tail = msgs.slice(-cfg.keepRecentTurns);
  const head = msgs.slice(0, msgs.length - cfg.keepRecentTurns);
  const prior = await store.summary(conversationId);

  const res = await client.complete({
    model: FAST_MODEL,
    maxOutputTokens: cfg.maxSummaryTokens,
    temperature: 0,
    system: [
      "You maintain a state summary of an ongoing conversation. Preserve FACTS, not narrative.",
      "Include: identities and roles, account and record identifiers with values, decisions made,",
      "stated preferences and constraints, amounts and dates, open questions, and unresolved issues.",
      "Drop: pleasantries, restated information already in the summary, and any speculation.",
      "Never invent. If something was not established, omit it.",
    ].join("\n"),
    messages: [
      ...(prior ? [{ role: "system" as const, content: `EXISTING SUMMARY (merge, do not duplicate):\n${prior.text}` }] : []),
      ...head.map(toWire),
    ],
  });
  if (res.stopReason === "max_tokens") return { compacted: false, summaryTokens: 0 };

  const summaryText = textOf(res.content);
  await store.putSummary(conversationId, {
    text: summaryText,
    coversMessageIds: head.map((m) => m.id),
    createdAt: new Date().toISOString(),
    recipeId: "conversation.state-summary.v2",
  });
  return { compacted: true, summaryTokens: measureTokens(summaryText) };
}
